def _components(grid):
    h = len(grid)
    seen = set()
    result = []
    for r in range(h):
        for c in range(len(grid[r])):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < len(grid[yy]) and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            result.append((color, cells))
    return result


def _guide(component):
    color, cells = component
    minr = min(r for r, c in cells)
    maxr = max(r for r, c in cells)
    minc = min(c for r, c in cells)
    maxc = max(c for r, c in cells)
    if maxr == minr or maxc == minc:
        return None
    for cr in (minr, maxr):
        for cc in (minc, maxc):
            shape = {(cr, c) for c in range(minc, maxc + 1)}
            shape.update((r, cc) for r in range(minr, maxr + 1))
            if cells == shape:
                return color, cells, (cr, cc)
    return None


def _shape(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return frozenset((r - r0, c - c0) for r, c in cells)


def _center(cells):
    n = len(cells)
    return (sum(r for r, c in cells) / n, sum(c for r, c in cells) / n)


def transform(grid):
    out = [row[:] for row in grid]
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    components = [comp for comp in _components(grid)
                  if comp[0] != background and len(comp[1]) > 1]
    guides = [g for comp in components if (g := _guide(comp)) is not None]
    if not guides:
        return out
    color, guide_cells, corner = max(
        guides,
        key=lambda g: (len(g[1]),
                       max(r for r, c in g[1]) - min(r for r, c in g[1]) +
                       max(c for r, c in g[1]) - min(c for r, c in g[1])))
    rest = [(col, cells) for col, cells in components if cells != guide_cells]

    pairs = []
    for i, (col1, cells1) in enumerate(rest):
        shape1 = _shape(cells1)
        for col2, cells2 in rest[i + 1:]:
            if _shape(cells2) != shape1:
                continue
            center1, center2 = _center(cells1), _center(cells2)
            d1 = (center1[0] - corner[0]) ** 2 + (center1[1] - corner[1]) ** 2
            d2 = (center2[0] - corner[0]) ** 2 + (center2[1] - corner[1]) ** 2
            target = cells1 if d1 > d2 else cells2
            pairs.append((max(d1, d2), min(d1, d2), len(shape1), target))
    if pairs:
        _, _, _, target = max(pairs, key=lambda item: (item[0], item[2], item[1]))
        for r, c in target:
            out[r][c] = color
    return out


